import { useState } from 'react';
import { Link } from 'react-router-dom';
import './Header.css';
import { IoClose, IoMenu } from "react-icons/io5";
import logo from '../assets/img/School_logo.svg';

const Header = () => {

    return (
        <>
            <nav className='Header'>
                <div className='school-logo-div'>
                    <img src={logo} alt='School logo' style={{ width: 46, height: 53, paddingLeft: 20 }} />
                    <h1 className='logo-large-heading' style={{ textAlign: 'justify' }}>ABUNDANT RAIN SCHOOL</h1>
                </div>
                <div className='nav-menu' id='nav_menu'>
                <ul className='nav-bar-options'>
                    <li><Link to="/" className={'link'}>Home</Link></li>
                    <li><Link to="/AboutUs" className={'link'}>About Us</Link></li>
                    <li><Link to="/Admissions" className={'link'}>Admissions</Link></li>
                    <li><Link to="/Gallery" className={'link'}>Gallery</Link></li>
                </ul>
                <div className='nav-close' id='nav_close'>
                <IoClose />
                </div>
                </div>
                <div className='nav-toggle' id='nav_toggle'>
                <IoMenu />
                </div>
            </nav>
        </>
    );
}

export default Header;